{
  "findings": [
    {
      "check_id": "AVD-AZU-0010",
      "title": "Network rules do not allow bypass for Microsoft Services",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "The bypass setting does not include 'AzureServices', which means trusted Microsoft Services cannot access the storage account. This could lead to operational issues or service disruptions."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Allow\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\", \"AzureServices\"]\n}",
  "fix_summary": "Added 'AzureServices' to the bypass list to allow trusted Microsoft Services to access the storage account, addressing the AVD-AZU-0010 finding."
}
